<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $invoice = \App\Models\Invoice::where("status", "unpaid")->latest()->first(); if($invoice) { $service = new \App\Services\PayMongoService(); $link = $service->createPaymentLink($invoice); if(isset($link["checkout_url"])) { $invoice->payment_url = $link["checkout_url"]; $invoice->save(); echo "Regenerated: ".$link["checkout_url"]; } }
